<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ArrowUpRight, MessageSquareText, MoveRight } from 'lucide-vue-next'
import { api } from '../api'
const stages = ['NEW','CONTACTED','QUALIFIED','VIEWING','NEGOTIATION','OFFER','CONTRACT','WON','LOST']
const leads = ref<any[]>([])
const tasks = ref<any[]>([])
const taskTitle = ref('')
const taskDue = ref('')
const taskSaving = ref(false)
const loading = ref(true)
const error = ref('')
const notes = ref<Record<string,string>>({})
const current = computed(() => leads.value.filter((lead) => !['WON','LOST'].includes(lead.stage)))
async function load() { loading.value = true; try { const [l,t] = await Promise.all([api.get('/leads'),api.get('/tasks')]); leads.value=l.data; tasks.value=t.data } catch (e:any) { error.value = e.response?.data?.message || 'Could not load leads.' } finally { loading.value = false } }
async function move(lead: any, stage: string) { try { await api.patch(`/leads/${lead.id}/stage`, { stage }); await load() } catch (e:any) { error.value = e.response?.data?.message || 'Could not update lead.' } }
async function addNote(lead: any) { if (!notes.value[lead.id]?.trim()) return; try { await api.post(`/leads/${lead.id}/activities`, { kind: 'NOTE', body: notes.value[lead.id] }); notes.value[lead.id] = ''; await load() } catch (e:any) { error.value = e.response?.data?.message || 'Could not add note.' } }
async function createTask() { if (!taskTitle.value.trim()) return; taskSaving.value=true; try { await api.post('/tasks',{title:taskTitle.value,...(taskDue.value?{dueAt:new Date(taskDue.value).toISOString()}:{})}); taskTitle.value=''; taskDue.value=''; await load() } catch(e:any) { error.value=e.response?.data?.message||'Could not create follow-up task.' } finally { taskSaving.value=false } }
async function completeTask(task:any) { try { await api.patch(`/tasks/${task.id}/complete`); await load() } catch(e:any) { error.value=e.response?.data?.message||'Could not update task.' } }
onMounted(load)
</script>

<template><section class="workspace-content"><div class="section-toolbar"><div><h2>Sales pipeline</h2><p>New inquiries become leads linked to the property and customer.</p></div><span class="count-pill">{{ current.length }} active</span></div><div v-if="error" class="notice error-notice">{{ error }}</div><div v-if="loading" class="loading-row">Loading lead pipeline…</div><template v-else><div v-if="!leads.length" class="empty-state compact-empty"><h3>No leads yet</h3><p>Property inquiries will appear here as new leads.</p><RouterLink class="button button-outline" to="/search">Browse the marketplace</RouterLink></div><div v-if="leads.length" class="pipeline-track"><section v-for="stage in stages" :key="stage" class="pipeline-column"><header><span class="stage-dot" :class="stage.toLowerCase()"></span><b>{{ stage.replaceAll('_',' ') }}</b><small>{{ leads.filter((lead) => lead.stage === stage).length }}</small></header><article v-for="lead in leads.filter((item) => item.stage === stage)" :key="lead.id" class="lead-card"><div class="lead-card-top"><span class="lead-avatar">{{ lead.name.split(' ').map((n:string)=>n[0]).join('').slice(0,2) }}</span><span><b>{{ lead.name }}</b><small>{{ lead.email }}</small><small v-if="lead.phone">{{ lead.phone }}</small></span><a v-if="lead.property" :href="`/property/${lead.property.slug}`" title="Open property"><ArrowUpRight :size="15" /></a></div><div v-if="lead.property" class="lead-property">{{ lead.property.title }}<small>{{ lead.property.city }} · PKR {{ Number(lead.property.price).toLocaleString() }}</small></div><div v-if="lead.activities?.length" class="lead-latest"><MessageSquareText :size="13" /> {{ lead.activities[0].body }}</div><form class="lead-note-form" @submit.prevent="addNote(lead)"><input v-model="notes[lead.id]" placeholder="Add a follow-up note…" /><button aria-label="Add note"><MoveRight :size="15" /></button></form><select :value="lead.stage" aria-label="Move lead to stage" @change="move(lead, ($event.target as HTMLSelectElement).value)"><option v-for="item in stages" :key="item" :value="item">Move to {{ item.toLowerCase() }}</option></select></article></section></div><div class="pipeline-summary"><span>Won: <b>{{ leads.filter((lead) => lead.stage === 'WON').length }}</b></span><span>Lost: <b>{{ leads.filter((lead) => lead.stage === 'LOST').length }}</b></span></div><section class="panel-card task-panel"><div class="section-toolbar"><div><h2>My follow-ups</h2><p>Personal tasks stay tied to your organization and assignee.</p></div><span class="count-pill">{{tasks.filter(t=>!t.completedAt).length}} open</span></div><form class="task-form" @submit.prevent="createTask"><input v-model="taskTitle" required maxlength="140" placeholder="Call Mariam about the viewing…"/><input v-model="taskDue" type="datetime-local" aria-label="Task due date"/><button class="button button-primary" :disabled="taskSaving">{{taskSaving?'Adding…':'Add task'}}</button></form><div class="task-list"><article v-for="task in tasks" :key="task.id" :class="{done:task.completedAt}"><button class="task-check" :class="{checked:task.completedAt}" :aria-label="task.completedAt?'Reopen task':'Complete task'" @click="completeTask(task)">{{task.completedAt?'✓':''}}</button><span><b>{{task.title}}</b><small>{{task.dueAt?new Date(task.dueAt).toLocaleString():'No due date'}}</small></span><small>{{task.completedAt?'Completed':'Open'}}</small></article><div v-if="!tasks.length" class="small-empty">No follow-ups yet. Add a task to keep your next action visible.</div></div></section></template></section></template>
